import {mkdir,writeFile,readFile,cp} from 'node:fs/promises';import path from 'node:path';
import {releaseHash} from '../../../scripts/release-record.mjs';
import {reviewVocabulary,retainSnapshot} from '../../../scripts/release-docs.mjs';
export async function documentationFixture(rendererRoot,base,revision){
 for(const name of ['CHANGELOG.md','SECURITY.md','LICENSE','docs/v0.0.0','schemas/v0.0.0','site/snapshots/v0.0.0'])await cp(path.join(rendererRoot,name),path.join(base,name),{recursive:true});const sourceManifest=JSON.parse(await readFile(path.join(rendererRoot,'site/versions.json'),'utf8'));const baseline=sourceManifest.snapshots.find(s=>s.version==='v0.0.0');if(!baseline)throw Error('Controlled documentation requires the retained specification baseline');const manifest={latest:'v0.0.0',snapshots:[baseline]};
 const put=async(file,text)=>{await mkdir(path.dirname(path.join(base,file)),{recursive:true});await writeFile(path.join(base,file),text);};
 for(const version of ['v0.1.0','v0.2.0']){
  const snapshot={version,status:'released',source:'docs/'+version,topics:['index','overview','glossary'],schema:'schemas/'+version+'/local-media-gallery.schema.json',examples:['schemas/'+version+'/examples/valid.json'],assets:['docs/'+version+'/asset.svg'],references:[{source:'brand/kit/reference.txt',name:'reference.txt',captured:'site/snapshots/'+version+'/reference.source',sha256:releaseHash('Retained fixture reference '+version+'\n')}],contracts:[{source:'schemas/'+version+'/fixture-contract.json',definition:'fixture',topic:'fixture-contract',title:'Fixture contract'}],additionalSchemas:[...(version==='v0.1.0'?[{source:'schemas/'+version+'/old-only.schema.json',topic:'old-only',title:'Historical schema topic'}]:[]),{source:'schemas/'+version+'/shared.schema.json',topic:'shared-schema',title:'Shared fixture schema'}]};
  await put(snapshot.source+'/index.md',`# Controlled documentation ${version}\n\n## Contract\n\nPrivate pipeline fixture. [Overview](overview.md#behavior), [Glossary](glossary.md), [schema](../../schemas/${version}/local-media-gallery.schema.json), [reference](../../brand/kit/reference.txt).\n\n![Retained fixture asset](asset.svg)\n`);await put(snapshot.source+'/overview.md',`# Fixture overview\n\n## Behavior\n\nVersion ${version} preserves its own historical explanation. [Contract](index.md#contract).\n`);await put(snapshot.source+'/glossary.md','# Glossary\n\n| Term | Definition | Primary reference and local usage |\n| --- | --- | --- |\n| Fixture | Controlled test input with no product publication claim | [Node testing](https://nodejs.org/api/test.html), [Local contract](index.md#contract) |\n');await put(snapshot.assets[0],'<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24"><title>Fixture square</title><rect width="24" height="24"/></svg>\n');await put(snapshot.references[0].captured,'Retained fixture reference '+version+'\n');await put(snapshot.schema,JSON.stringify({$schema:'https://json-schema.org/draft/2020-12/schema',$id:'urn:local-media-gallery:'+version.slice(1),'x-release-version':version.slice(1),type:'object',additionalProperties:false,properties:{value:{type:'string'}},required:['value'],$defs:{fixture:{type:'object',properties:{name:{const:version}},required:['name'],additionalProperties:false}}})+'\n');await put(snapshot.examples[0],'{"value":"accepted"}\n');await put(snapshot.contracts[0].source,JSON.stringify({name:version})+'\n');for(const extra of snapshot.additionalSchemas)await put(extra.source,JSON.stringify({$schema:'https://json-schema.org/draft/2020-12/schema','x-release-version':version.slice(1),type:'string'})+'\n');
  const review=await reviewVocabulary(base,snapshot,{reviewer:'S021 controlled fixture campaign',reviewedAt:'2026-10-31',notes:'Reviewed fixture term, definition, primary learning reference and local usage; no real product release is represented.',major:false});await retainSnapshot({fromRoot:base,toRoot:base,snapshot,sourceRevision:revision,review});manifest.snapshots.push(snapshot);
 }
 await put('site/versions.json',JSON.stringify(manifest,null,2)+'\n');return manifest;
}
